// Verifies a StockAI webhook delivery (signature + age) and drops repeats.
// Needs the signing secret, shown once when the webhook was created, in the n8n
// environment variable STOCKAI_WEBHOOK_SECRET, and NODE_FUNCTION_ALLOW_BUILTIN=crypto.
const crypto = require('crypto');
const secret = $env.STOCKAI_WEBHOOK_SECRET;
if (!secret) throw new Error('Set STOCKAI_WEBHOOK_SECRET to the signing secret of this webhook');

const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
const headers = $input.first().json.headers || {};
const header = headers['x-stockai-signature'] || '';
const parts = Object.fromEntries(header.split(',').map(p => p.split('=')).filter(p => p.length === 2));
const t = parseInt(parts.t, 10);
if (!t || Math.abs(Date.now() / 1000 - t) > 300) throw new Error('Rejected: the signature timestamp is missing or too old');

const expected = crypto.createHmac('sha256', secret).update(`${t}.`).update(raw).digest('hex');
const given = String(parts.v1 || '');
const a = Buffer.from(expected);
const b = Buffer.from(given);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) throw new Error('Rejected: the signature does not match');

const event = JSON.parse(raw.toString('utf8'));

// A delivery can arrive more than once: handle each event id one time.
const seen = $getWorkflowStaticData('global');
seen.ids = seen.ids || {};
if (seen.ids[event.id]) return [];
seen.ids[event.id] = Date.now();
for (const [id, at] of Object.entries(seen.ids)) {
  if (Date.now() - at > 86400000) delete seen.ids[id];
}
return [{ json: event }];
